// Function to fetch followers with error handling
function fetchFollowers($url, $authToken, $clientID) {
  $curl = curl_init($url);
  curl_setopt($curl, CURLOPT_HTTPHEADER, [
    'Authorization: Bearer ' . $authToken,
    'Client-ID: ' . $clientID
  ]);
  curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
  $response = curl_exec($curl);
  // Any non-200 Helix reply (expired token, 401, rate limit) is a failed fetch,
  // so the sync never treats an error body as "no followers" and wipes the table.
  $httpCode = (int) curl_getinfo($curl, CURLINFO_HTTP_CODE);
  // Beta: an expired token ends the sign-in instead of showing an error.
  if ($response !== false && $httpCode === 401) beta_twitch_401();
  if ($response !== false && $httpCode !== 200) {
    error_log('beta followers: helix http ' . $httpCode);
    return false;
  }
  if ($response === false) {
    // Handle cURL error
    $errorMessage = 'cURL error: ' . curl_error($curl);
    $errorDetails = 'URL: ' . curl_getinfo($curl, CURLINFO_EFFECTIVE_URL) . ' | HTTP Code: ' . curl_getinfo($curl, CURLINFO_HTTP_CODE);
    error_log('beta followers: ' . $errorMessage . ' | ' . $errorDetails);
return false;
  }
return $response;
}
